INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by)
VALUES ('TensorLBM', 'm17013 KPI-LBM-VERIFIED-CAPS', 17085, 1, $json${"verdict_level_claim": 1, "audited_mission": 17013, "audited_commit": "bb45e2dd (m17013: matured mission deliverables), merge 7255cf1d, PR #1977", "impl_files": ["/root/tp-agent/work/m17085/benchmarks/verified/nwt_stokes2/run.py", "/root/tp-agent/work/m17085/src/tensorlbm/nwt/stokes2.py"], "impl_note": "run.py (136 lines, driver written by m17013) verifies src/tensorlbm/nwt/stokes2.py, which was NOT written by m17013: added 2026-11-08 by 551cff07 (m5712). No new functional capability implemented in this mission -> L2 not met.", "entry": "/root/tp-agent/work/m17085/benchmarks/verified/nwt_stokes2/run.py", "run_artifacts": ["/root/tp-agent/work/m17085/benchmarks/verified/nwt_stokes2/result.json", "/root/tp-agent/work/m17085/docs/audit_m17013/audit.json", "/root/tp-agent/work/m17085/docs/audit_m17013/AUDIT_m17013.md", "/root/tp-agent/work/m17085/docs/audit_m17013/fig_audit_m17013.png"], "tests": ["tests/test_nwt_stokes2.py (9 passed, re-run by auditor; file PRE-EXISTING 551cff07/m5712, not new evidence of this mission)", "docs/audit_m17013/independent_audit.py::probe_fresh_run (fresh re-run 12/12 PASS, result_json_identical_to_shipped=True)", "docs/audit_m17013/independent_audit.py::probe_mutations[control] (mutation B a2 x2 -> 11/12 FAIL: gates have detection power on covered subset)", "docs/audit_m17013/independent_audit.py::probe_mutations[A] (mutation A elevation()->12345 -> still 12/12 PASS: claimed free-surface physics NOT covered)"], "integration_callers": ["/root/tp-agent/work/m17085/src/tensorlbm/nwt/tank.py:42 from .stokes2 import Stokes2Wave (PRE-EXISTING coupling, not delivered by m17013)", "/root/tp-agent/work/m17085/benchmarks/verified/nwt_stokes2/run.py:51 from tensorlbm.nwt.stokes2 import Stokes2Wave, dispersion_k, phase_speed, group_speed (driver imports the analytic module only; 0 imports of tensorlbm.solver / d2q9 / nwt.tank / nwt.wavemaker / vof_free_surface -> runs_solver=False)"], "benchmark": {"metric": "closed-form identity residuals of the Stokes-2 analytic module", "machine_referee": "SELECT case_name,metric,tolerance FROM tensor_benchmark_cases WHERE anchor_slug='KPI-LBM-VERIFIED-CAPS' -> 0 rows (anchor has no referee row)", "ref_vs_got": {"dispersion_omega2_vs_g_k_tanh_kh": {"rel_dev_max": 1.49e-16, "declared_tol": 1e-12, "pass": true}, "deep_shallow_phase_and_group_speed": {"rel_dev_max": 1.43e-07, "declared_tol": "1e-6/2e-6/1e-5/1e-4", "pass": true}, "second_harmonic_a2_vs_closed_form": {"rel_dev": 0.0, "declared_tol": 1e-12, "pass": true}, "period_wavenumber_roundtrip": {"rel_dev": 0.0, "declared_tol": 1e-12, "pass": true}}, "why_not_L4": "(1) ref and got are the same closed form re-typed in the driver -> self-consistency, not independent physical validation; (2) no grid, no time stepping, no two-grid convergence -> violates benchmarks/STATUS.md:5 'within 3% AND mesh-converged (two grids, span <=3%)'; (3) the solver-side case of the same capability benchmarks/pending/nwt_stokes2_2d has NO machine verdict file (ledger machine=unknown), so no LBM solution vs Stokes-2 comparison exists", "gate_count_note": "12 gate calls = 9 distinct gate names (dispersion repeated 4x with (k,h)); '12 gates' is call count, not capability count"}, "repro_cmd": "cd /root/tp-agent/work/m17085 && python3 benchmarks/verified/nwt_stokes2/run.py   # -> nwt_stokes2: 12/12 gates -> PASS ; and python3 docs/audit_m17013/independent_audit.py   # -> audit.json incl. mutation probes A/B", "external_anchor": ["Dean & Dalrymple 1991, Water Wave Mechanics for Engineers and Scientists, sec 4.3 (eqs. 3.51-3.56 in the module docstring); Airy 1845; Stokes 1847", "static textbook closed form only: no experimental discrete data and no field/benchmark dataset -> external validation NOT claimed; L5 impossible"], "coverage_gap": {"claimed_in_run_py_docstring_but_never_exercised": ["surface elevation eta(x,t)", "free-surface boundary-condition residual O(eps^2)", "divergence-free / potential-matching velocity field"], "surface_call_sites_present_in_driver": 0, "mutation_A_elevation_destroyed_still_passes": true}, "ledger_arithmetic": {"header_before": "verified 79", "header_after": "verified 81", "verified_dirs_before_commit": 80, "verified_dirs_after_commit": 81, "explanation": "only ONE directory (nwt_stokes2) was added by bb45e2dd; nscbc_outlet_reflection already existed in the parent tree, so +1 of the +2 is a stale-count correction; status_ledger.py counts directories (no content gate), so a bare directory inflates the KPI", "registration_defects": ["no README.md in benchmarks/verified/nwt_stokes2", "human-table note appended after <!-- STATUS_LEDGER:END --> i.e. outside the ## verified/ section -> ledger still shows nwt_stokes2 | no (uncovered)"]}, "report_debt": "tensor_dev_missions.id=17013 report_owed=t, report_id NULL, tensor_reports rows for mission 17013 = 0; mission ended fail_stage=budget_exhausted+forced_finish after 60 tool calls -> no paper-grade report ever published for this claim", "level_rationale": "L1 met (12/12 machine-checkable analytic/unit gates, fresh re-run bitwise-identical, control mutation detected). L2 NOT met: no new functional capability implemented (stokes2.py pre-exists, added by m5712/551cff07); deliverable is a verification driver. L3 NOT met: 0 solver imports / 0 call sites of the claimed free-surface surfaces; existing coupling in nwt/tank.py:42 is pre-existing, not delivered here. L4 NOT met: no mesh/no convergence and the repo's own verified acceptance (STATUS.md:5) is not satisfied; solver-side nwt_stokes2_2d has no machine verdict. L5 NOT met. Verdict = L1, promotion of this case to the 'verified capability' KPI is overstated -> request changes / reopen.", "disposition": "request_changes", "remediation": ["downgrade/relabel benchmarks/verified/nwt_stokes2 as analytic anchor (or add README stating reference self-verification) and delete the two unsupported docstring claims", "add gates for surface_bc_residual (eps^2 decay) and 2D velocity-field continuity/curl so mutation-A-class sabotage is caught", "raise to verified only via benchmarks/pending/nwt_stokes2_2d run_acceptance.py all -> results.json (C1 1% / C2 A1 3% / A2 10% / C3 5% / C4 0.5%/period / C5 two-grid 3%)", "make status_ledger --check treat 'verified dir without README or convergence evidence' as a hard violation so the directory-count KPI cannot be inflated"]}$json$, 'board-audit')
